IF_NEXT_23:
IF_END_22:
    JSR update_player
    JSR update_snowballs
    ; UPDATE_ENEMIES: advance enemy AI and movement
    JSR UPDATE_ENEMIES_RUNTIME
    ; ===== SHOW_LEVEL builtin =====
    JSR SHOW_LEVEL_RUNTIME
    LDD #0
    STD RESULT
    JSR draw_player
