; Function: state_game_over (Bank #0)
state_game_over:
    ; PRINT_TEXT: Print text at position
    LDD #-35
    STD VAR_ARG0
    LDD #20
    STD VAR_ARG1
    LDX #PRINT_TEXT_STR_62413928761410      ; Pointer to string in helpers bank
    STX VAR_ARG2
    JSR VECTREX_PRINT_TEXT
    LDD #0
    STD RESULT
    ; PRINT_TEXT: Print text at position
    LDD #-25
    STD VAR_ARG0
    LDD #-10
    STD VAR_ARG1
    LDX #PRINT_TEXT_STR_78726770      ; Pointer to string in helpers bank
    STX VAR_ARG2
    JSR VECTREX_PRINT_TEXT
    LDD #0
    STD RESULT
    ; PRINT_NUMBER(x, y, num)
    LDD #30
    STD VAR_ARG0    ; X position
    LDD #-10
    STD VAR_ARG1    ; Y position
    LDD >VAR_SCORE
    STD VAR_ARG2    ; Number value
    JSR VECTREX_PRINT_NUMBER
    LDD #0
    STD RESULT
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    BNE .J1B1_1_ON
    LDD #0
    BRA .J1B1_1_END
.J1B1_1_ON:
    LDD #1
.J1B1_1_END:
    STD RESULT
    LBEQ IF_NEXT_45
    ; STOP_MUSIC: Stop music playback
    JSR STOP_MUSIC_RUNTIME
    LDD #0
    STD RESULT
    LDD >VAR_STATE_TITLE
    STD VAR_GAME_STATE
    LBRA IF_END_44
IF_NEXT_45:
IF_END_44:
    RTS

