; Function: draw_player (Bank #0)
draw_player:
    ; SET_INTENSITY: Set drawing intensity
    LDD #65
    TFR B,A         ; Intensity (8-bit) — B already holds low byte
    STA DRAW_VEC_INTENSITY  ; DSWM reads this for every path drawn
    LDD #0
    STD RESULT
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_57_TRUE
    LDD #0
    LBRA .CMP_57_END
.CMP_57_TRUE:
    LDD #1
.CMP_57_END:
    LBEQ IF_NEXT_123
    ; DRAW_VECTOR: Draw vector asset at position
    ; Asset: player_jump (index=6, 18 paths)
    LDD >VAR_PLAYER_X
    TFR B,A       ; X position (low byte) — B already holds it
    STA TMPPTR    ; Save X to temporary storage
    LDD >VAR_PLAYER_Y
    TFR B,A       ; Y position (low byte) — B already holds it
    STA TMPPTR+1  ; Save Y to temporary storage
    LDA TMPPTR    ; X position
    STA DRAW_VEC_X
    LDA TMPPTR+1  ; Y position
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA MIRROR_X
    CLR MIRROR_Y
    LDX #6        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    CLR DRAW_VEC_INTENSITY  ; Reset: next DRAW_VECTOR uses .vec intensities
    LDD #0
    STD RESULT
    LBRA IF_END_122
IF_NEXT_123:
IF_END_122:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_ON_GROUND
    CMPD TMPVAL
    LBEQ .CMP_58_TRUE
    LDD #0
    LBRA .CMP_58_END
.CMP_58_TRUE:
    LDD #1
.CMP_58_END:
    LBEQ IF_NEXT_125
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PLAYER_VX
    CMPD TMPVAL
    LBEQ .CMP_59_TRUE
    LDD #0
    LBRA .CMP_59_END
.CMP_59_TRUE:
    LDD #1
.CMP_59_END:
    LBEQ IF_NEXT_127
    ; DRAW_VECTOR: Draw vector asset at position
    ; Asset: player_idle (index=5, 18 paths)
    LDD >VAR_PLAYER_X
    TFR B,A       ; X position (low byte) — B already holds it
    STA TMPPTR    ; Save X to temporary storage
    LDD >VAR_PLAYER_Y
    TFR B,A       ; Y position (low byte) — B already holds it
    STA TMPPTR+1  ; Save Y to temporary storage
    LDA TMPPTR    ; X position
    STA DRAW_VEC_X
    LDA TMPPTR+1  ; Y position
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA MIRROR_X
    CLR MIRROR_Y
    LDX #5        ; Asset index for lookup
    JSR DRAW_VECTOR_BANKED  ; Draw with automatic bank switching
    CLR DRAW_VEC_INTENSITY  ; Reset: next DRAW_VECTOR uses .vec intensities
    LDD #0
    STD RESULT
    LBRA IF_END_126
IF_NEXT_127:
    ; DRAW_ANIM: draw animation 'player_walk'
    LDD >VAR_PLAYER_X
    TFR B,A
    STA DRAW_VEC_X
    LDD >VAR_PLAYER_Y
    TFR B,A
    STA DRAW_VEC_Y
    LDD >VAR_PLAYER_FACING
    TFR B,A
    STA >MIRROR_X
    STA >DRAW_ANIM_MIRROR_X
    CLR >MIRROR_Y
    LDA #$7F
    STA DRAW_ANIM_SCALE
    CLR DRAW_ANIM_SPEED_MUL
    LDX #_ANIM_PLAYER_WALK
    LDU #ANIM_PLAYER_WALK_STATE
    JSR DRAW_ANIM_RUNTIME
    LDD #0
    STD RESULT
IF_END_126:
    LBRA IF_END_124
IF_NEXT_125:
IF_END_124:
    RTS

