    FCB 0                   ; loop=false
    FCB 0                    ; pad (keeps 4-byte entry stride)
    FCB $FF   ; action 1 (walk) sprite_idx ($FF=none)
    FCB 1                   ; sprite_type: 0=vec, 1=vanim
    FCB 1                   ; loop=true
    FCB 0                    ; pad (keeps 4-byte entry stride)


